package com.finsight.service; import com.finsight.domain.*; import com.finsight.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*; @Service public class CreditApplicationService {final CreditApplicationRepository apps;final CustomerRepository customers;final AuditEventRepository audit;final RiskAssessmentService risk;public CreditApplicationService(CreditApplicationRepository a,CustomerRepository c,AuditEventRepository e,RiskAssessmentService r){apps=a;customers=c;audit=e;risk=r;}public List<CreditApplication> all(){return apps.findAllByOrderByCreatedAtDesc();}public CreditApplication get(Long id){return apps.findById(id).orElseThrow(()->new IllegalArgumentException("Application not found"));}@Transactional public CreditApplication create(Long cid,Double amount,Integer tenure){Customer c=customers.findById(cid).orElseThrow(()->new IllegalArgumentException("Customer not found"));CreditApplication a=new CreditApplication();a.setCustomer(c);a.setRequestedAmount(amount);a.setTenureMonths(tenure);CreditApplication x=apps.save(a);log(x.getId(),"APPLICATION_CREATED","Credit application submitted","DEMO_ANALYST");return x;}@Transactional public CreditApplication assess(Long id){CreditApplication a=get(id);var r=risk.assess(a);a.setRiskScore(r.score());a.setRiskLevel(r.level());a.setStatus(ApplicationStatus.RISK_ASSESSED);a.setUpdatedAt(LocalDateTime.now());CreditApplication x=apps.save(a);log(id,"RISK_ASSESSED","Risk score "+r.score()+" ("+r.level()+")","RISK_ENGINE");return x;}@Transactional public CreditApplication decide(Long id,String decision,String reason){CreditApplication a=get(id);if(a.getRiskScore()==null)throw new IllegalStateException("Risk assessment is required before a decision");if("APPROVE".equalsIgnoreCase(decision))a.setStatus(ApplicationStatus.APPROVED);else if("REJECT".equalsIgnoreCase(decision))a.setStatus(ApplicationStatus.REJECTED);else throw new IllegalArgumentException("Decision must be APPROVE or REJECT");a.setDecisionReason(reason);a.setUpdatedAt(LocalDateTime.now());CreditApplication x=apps.save(a);log(id,"DECISION_MADE","Decision "+a.getStatus()+": "+reason,"DEMO_ANALYST");return x;}public List<AuditEvent> audit(Long id){return audit.findByApplicationIdOrderByCreatedAtAsc(id);}void log(Long id,String type,String desc,String actor){AuditEvent e=new AuditEvent();e.setApplicationId(id);e.setEventType(type);e.setDescription(desc);e.setActor(actor);audit.save(e);}}
